<template><main class="auth-page"><router-link class="brand" to="/"><span>Y</span><strong>Yu Like</strong></router-link><section class="auth-card section-card"><div class="intro"><span>WELCOME BACK</span><h1>欢迎回来</h1><p>登录后继续创作、讨论，并使用你的 AI 助手。</p></div><form @submit.prevent="submit"><label class="form-field">用户名<input v-model.trim="form.username" class="input-control" autocomplete="username" required placeholder="请输入用户名"/></label><label class="form-field">密码<div class="password"><input v-model="form.password" class="input-control" :type="showPassword?'text':'password'" autocomplete="current-password" required placeholder="请输入密码"/><button type="button" @click="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</button></div></label><ErrorAlert :message="userStore.error"/><button class="btn btn-primary submit" :disabled="userStore.loading">{{userStore.loading?'正在登录…':'登录'}}</button></form><footer>还没有账号？<router-link to="/register">立即注册</router-link></footer></section></main></template>
<script setup>
import { reactive,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import ErrorAlert from '../components/common/ErrorAlert.vue';import { useUserStore } from '../stores/user';
const route=useRoute(),router=useRouter(),userStore=useUserStore(),showPassword=ref(false);const form=reactive({username:'',password:''});async function submit(){const ok=await userStore.login(form);if(ok)router.push(String(route.query.redirect||'/'));}
</script>
<style scoped>.auth-page{display:grid;min-height:100vh;place-items:center;align-content:center;gap:22px;padding:24px;background:#f7f8fb}.brand{display:flex;align-items:center;gap:9px}.brand span{display:grid;width:36px;height:36px;place-items:center;border-radius:10px;background:#0f766e;color:white;font-weight:950}.auth-card{width:min(440px,100%);padding:32px}.intro span{color:#0f766e;font-size:10px;font-weight:900;letter-spacing:.12em}.intro h1{margin:6px 0;font-size:30px}.intro p{margin:0 0 24px;color:#64748b;line-height:1.6}form{display:grid;gap:17px}.password{position:relative}.password input{padding-right:62px}.password button{position:absolute;top:50%;right:10px;border:0;background:none;transform:translateY(-50%);color:#0f766e;font-size:12px;font-weight:800}.submit{width:100%;margin-top:3px}.auth-card footer{border-top:1px solid #f1f5f9;margin-top:24px;padding-top:20px;color:#64748b;text-align:center;font-size:13px}.auth-card footer a{color:#0f766e;font-weight:850}</style>
